contracts.definition:
send(sessionId, segments): Promise<void>
  // 内部逻辑（line 250-260 附近）：
  const images = await extractImages(segments, ...)
  if (images && images.length > 0) {
    const modelId = session.list.find(s => s.id === sid)?.modelId ?? ''
    if (!resolveSupportsVision(modelId, settings.providers)) {
      if (!warnedModels.current.value.models.has(modelId)) {
        useToast().warning(t('panel.visionNotSupportedWarning', { modelName: modelId, count: images.length }))
        warnedModels.update(s => { s.models.add(modelId) })
      }
    }
  }
  await chatApi.send(sid, promptText, images)  // 不阻断，继续发送
